package cn.zhuatech.cafm.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class FacilityWorkOrderClosureServiceTest{private final FacilityWorkOrderClosureService service=new FacilityWorkOrderClosureService();@Test void closesCompleteOrder(){var r=service.assess(new FacilityWorkOrderClosureService.Request("W1",true,true,true,true,true,true,true,true));assertThat(r.decision()).isEqualTo(FacilityWorkOrderClosureService.Decision.CLOSE);}@Test void blocksSafetyAndEvidenceGaps(){var r=service.assess(new FacilityWorkOrderClosureService.Request("W2",true,false,false,false,false,true,true,true));assertThat(r.blockers()).hasSize(4);}@Test void reviewsAcceptanceCostAndPrevention(){var r=service.assess(new FacilityWorkOrderClosureService.Request("W3",false,true,true,true,false,false,false,false));assertThat(r.actions()).hasSize(3);}}
